def transform(grid):
    h, w = len(grid), len(grid[0])

    # Horizontal guide stripes define a repeating row pattern.
    stripes = {
        r: row[0]
        for r, row in enumerate(grid)
        if row[0] != 0 and all(v == row[0] for v in row)
    }
    if stripes:
        n = len(stripes)
        by_residue = {r % n: color for r, color in stripes.items()}
        return [[by_residue[r % n]] * w for r in range(h)]

    # For diagonal guides, group cells by each possible diagonal invariant.
    cells = [(r, c, grid[r][c])
             for r in range(h) for c in range(w) if grid[r][c] != 0]
    sum_groups = {}
    diff_groups = {}
    for r, c, color in cells:
        sum_groups.setdefault(r + c, []).append(color)
        diff_groups.setdefault(r - c, []).append(color)

    def score(groups):
        return sum(len(colors) for colors in groups.values()
                   if len(set(colors)) == 1)

    groups = sum_groups if score(sum_groups) >= score(diff_groups) else diff_groups
    lines = {key: colors[0] for key, colors in groups.items()
             if len(set(colors)) == 1}
    n = len(lines)
    by_residue = {key % n: color for key, color in lines.items()}

    use_sum = groups is sum_groups
    return [
        [by_residue[((r + c) if use_sum else (r - c)) % n]
         for c in range(w)]
        for r in range(h)
    ]
